<script setup>import { ref } from 'vue';import { Send, Paperclip, Smile } from 'lucide-vue-next';const props=defineProps({disabled:Boolean,name:String});const emit=defineEmits(['send']);const text=ref('');function submit(){if(props.disabled||!text.value.trim())return;emit('send',text.value.trim());text.value=''}</script>
<template><form @submit.prevent="submit"><button type="button" aria-label="Attach file" :disabled="disabled"><Paperclip :size="19"/></button><textarea v-model="text" rows="1" :disabled="disabled" :placeholder="disabled?`Claim this chat to reply to ${name}…`:`Type a reply to ${name}…`" aria-label="Reply message" @keydown.enter.exact.prevent="submit"/><button type="button" aria-label="Add emoji" :disabled="disabled"><Smile :size="19"/></button><button class="send" aria-label="Send message" :disabled="disabled||!text.trim()"><Send :size="18"/></button></form></template>
<style scoped>form{padding:13px 17px;border-top:1px solid #eef0f5;display:flex;align-items:center;gap:8px;background:#fff}textarea{resize:none;min-height:42px;max-height:100px;background:#f8f9fb;padding:10px 12px}button{border:0;background:none;color:var(--muted);display:grid;place-items:center;padding:8px}.send{width:40px;height:40px;border-radius:10px;background:var(--primary);color:#fff}.send:disabled{background:#d5d8e2}</style>
